import java.util.Scanner;
public class JRentCar3 {
	public static void main(String[] args) {
		//Khatwa 1: Iqra al-madkholat min wakil ijarat al-sayarat
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil 'umr al-ameel:");
		int age = scan.nextInt();
		System.out.println("Adkhil ma idha kana laday al-ameel rukhsa qiyada (true or false):");
		boolean hasLicense = scan.nextBoolean();		
		System.out.println("Adkhil mablagh al-aitiman lil-ameel:");
		int credit = scan.nextInt();
		scan.close();
		//Khatwa 2: Iktub al-ta'bir al-buliyani li-tahdid in kana al-zubun yastati' istikhdam sayara
		boolean canRentCar = hasLicense && (age >= 21 || credit >= 10000);
		System.out.println(canRentCar);
	}
}
